def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(value):
        value = value or ""
        marker = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        return digits

    def valid_phone(value):
        return (
            len(value) == 10
            and value.isdigit()
            and value[0] not in {"0", "1"}
        )

    def normalize_zip(value):
        value = (value or "").strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value and (value.isupper() or value.islower()):
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def is_opted_out(value):
        return (value or "").strip().lower() in {
            "y", "yes", "true", "1"
        }

    normalized_rows = []

    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        email_ok = valid_email(email)
        phone_ok = valid_phone(phone)

        if not email_ok and not phone_ok:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"] or "")
            if tag.strip()
        }

        normalized_rows.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "zip": normalize_zip(row["zip"]),
            "tags": tags,
            "opted_out": is_opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
            "source": (row["source"] or "").strip().lower(),
        })

    count = len(normalized_rows)
    parent = list(range(count))
    size = [1] * count

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return

        if size[left_root] < size[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        size[left_root] += size[right_root]

    email_owner = {}
    phone_last_name_owner = {}

    for position, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = position
            else:
                union(position, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = position
            else:
                union(position, previous)

    groups = {}
    for position, row in enumerate(normalized_rows):
        groups.setdefault(find(position), []).append(row)

    def choose(group, field):
        candidates = [row for row in group if row[field] != ""]
        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["index"],
            ),
        )
        return chosen[field]

    output = []

    for group in sorted(
        groups.values(),
        key=lambda members: min(row["index"] for row in members),
    ):
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group)

        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
